// Reference solution
function cwndTrace(ssthresh, rounds, timeouts) {
  var cwnd = 1, st = ssthresh, out = [];
  for (var r = 1; r <= rounds; r++) {
    out.push(cwnd);
    if (timeouts.indexOf(r) >= 0) { st = Math.max(2, Math.floor(cwnd / 2)); cwnd = 1; }
    else if (cwnd < st) cwnd = Math.min(cwnd * 2, st);
    else cwnd = cwnd + 1;
  }
  return out;
}
